<script>document.querySelectorAll('[data-doc-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-doc-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-doc-panel]').forEach(x=>x.hidden=x.dataset.docPanel!==b.dataset.docTab)});const c=document.getElementById('signatureCanvas');if(c){const x=c.getContext('2d'),d=document.getElementById('signatureData');let draw=false,ink=false;function size(){const r=c.getBoundingClientRect(),ratio=window.devicePixelRatio||1;c.width=r.width*ratio;c.height=r.height*ratio;x.setTransform(ratio,0,0,ratio,0,0);x.lineWidth=2.6;x.lineCap='round';x.strokeStyle='#17243b'}function p(e){const r=c.getBoundingClientRect(),s=e.touches?e.touches[0]:e;return{x:s.clientX-r.left,y:s.clientY-r.top}}function start(e){draw=ink=true;const q=p(e);x.beginPath();x.moveTo(q.x,q.y);e.preventDefault()}function move(e){if(!draw)return;const q=p(e);x.lineTo(q.x,q.y);x.stroke();e.preventDefault()}function end(){if(!draw)return;draw=false;d.value=c.toDataURL('image/png')}size();c.addEventListener('mousedown',start);c.addEventListener('mousemove',move);window.addEventListener('mouseup',end);c.addEventListener('touchstart',start,{passive:false});c.addEventListener('touchmove',move,{passive:false});c.addEventListener('touchend',end);document.getElementById('clearSignature').onclick=()=>{x.clearRect(0,0,c.width,c.height);ink=false;d.value=''};document.getElementById('signatureForm').onsubmit=e=>{if(!ink||!d.value){e.preventDefault();alert('Please draw your signature before signing.')}}}</script></body></html>
